import { cva } from '@gentleduck/variants'

export const typesetVariants = cva('typeset', {
  defaultVariants: {
    size: 'default',
  },
  variants: {
    size: {
      default: '',
      lg: '[--typeset-flow:1.4em] [--typeset-leading:1.8] [--typeset-size:1.125rem]',
      sm: '[--typeset-flow:1em] [--typeset-leading:1.65] [--typeset-size:0.875rem]',
    },
  },
})

/*
 * Prose styles for rendered HTML and markdown. Wrap content in `.typeset`.
 * --typeset-size, --typeset-leading, and --typeset-flow drive every size and gap.
 * Blocks only get `margin-block-start`, so streamed content never shifts what is already on screen.
 * Opt out with `not-typeset` or `data-not-typeset`; a nested `.typeset` opts back in.
 */

/* Registered so an `em` value resolves once on `.typeset` instead of per heading size. */
@property --typeset-flow {
  syntax: "<length>";
  inherits: true;
  initial-value: 1.25rem;
}

@layer components {
  .typeset {
    --typeset-font-body: inherit;
    --typeset-font-heading: var(--font-heading, inherit);
    --typeset-font-mono: var(--font-mono, ui-monospace, monospace);
    --typeset-size: 1em;
    --typeset-leading: 1.75;
    --typeset-flow: 1.25em;

    font-family: var(--typeset-font-body);
    font-size: var(--typeset-size);
    line-height: var(--typeset-leading);
    overflow-wrap: break-word;
  }

  /* A small bump on phones, where body text reads small. */
  @media (width < 40rem) {
    .typeset {
      font-size: calc(var(--typeset-size) * 1.0625);
    }
  }

  .typeset > * + * {
    margin-block-start: var(--typeset-flow);
  }

  .typeset
    :where(*):not(
      :where(:is(.not-typeset, [data-not-typeset]), :is(.not-typeset, [data-not-typeset]) *):not(
        :where(:is(.not-typeset, [data-not-typeset]) .typeset *)
      )
    ) {
    &:where(* + :is(p, ul, ol, dl, pre, blockquote, table, figure, details, hr, h1, h2, h3, h4, h5, h6)) {
      margin-block-start: var(--typeset-flow);
    }

    &:where(h1, h2, h3, h4, h5, h6) {
      font-family: var(--typeset-font-heading);
      font-weight: 600;
      letter-spacing: -0.01em;
      line-height: 1.3;
      scroll-margin-block-start: 5rem;
      text-wrap: balance;
    }

    &:where(h1) {
      font-size: 2.25em;
      letter-spacing: -0.025em;
      line-height: 1.1;
    }

    &:where(h2) {
      font-size: 1.5em;
      letter-spacing: -0.02em;
      line-height: 1.25;
    }

    &:where(h3) {
      font-size: 1.25em;
    }

    &:where(h4) {
      font-size: 1.125em;
    }

    &:where(h5, h6) {
      font-size: 1em;
    }

    &:where(* + :is(h1, h2)) {
      margin-block-start: calc(var(--typeset-flow) * 2.25);
    }

    &:where(* + :is(h3, h4, h5, h6)) {
      margin-block-start: calc(var(--typeset-flow) * 1.5);
    }

    &:where(:is(h1, h2, h3, h4, h5, h6) + *) {
      margin-block-start: calc(var(--typeset-flow) * 0.5);
    }

    &:where(a) {
      color: inherit;
      font-weight: 500;
      text-decoration-color: color-mix(in oklab, currentColor 35%, transparent);
      text-decoration-line: underline;
      text-decoration-thickness: from-font;
      text-underline-offset: 0.25em;
      transition: text-decoration-color 150ms;
    }

    &:where(a:hover) {
      text-decoration-color: currentColor;
    }

    &:where(strong, b) {
      font-weight: 600;
    }

    &:where(em, i) {
      font-style: italic;
    }

    &:where(code) {
      font-family: var(--typeset-font-mono);
      font-size: 0.875em;
    }

    &:where(:not(pre) > code) {
      background-color: var(--muted);
      border-radius: calc(var(--radius) - 4px);
      padding: 0.15em 0.35em;
    }

    &:where(kbd) {
      border: 1px solid var(--border);
      border-block-end-width: 2px;
      border-radius: calc(var(--radius) - 4px);
      font-family: var(--typeset-font-mono);
      font-size: 0.8em;
      padding: 0.1em 0.4em;
    }

    &:where(mark) {
      background-color: color-mix(in oklab, var(--warning, oklch(0.85 0.16 85)) 35%, transparent);
      border-radius: 0.2em;
      color: inherit;
      padding: 0 0.15em;
    }

    &:where(small) {
      font-size: 0.875em;
    }

    &:where(sub, sup) {
      font-size: 0.75em;
      line-height: 0;
    }

    &:where(abbr[title]) {
      cursor: help;
      text-decoration: underline dotted;
    }

    &:where(p, li, blockquote, dd, figcaption) {
      text-wrap: pretty;
    }

    &:where(ul) {
      list-style-type: disc;
      padding-inline-start: 1.5em;
    }

    &:where(ol) {
      list-style-type: decimal;
      padding-inline-start: 1.5em;
    }

    &:where(ul ul) {
      list-style-type: circle;
    }

    &:where(ol ol) {
      list-style-type: lower-alpha;
    }

    /* GFM task lists (`- [ ]`); remark-gfm marks them with `contains-task-list`. */
    &:where(.contains-task-list) {
      list-style-type: none;
      padding-inline-start: 0.25em;
    }

    &:where(li > input[type="checkbox"]) {
      margin-inline-end: 0.5em;
      vertical-align: -0.1em;
    }

    &:where(li + li, li > :is(ul, ol)) {
      margin-block-start: calc(var(--typeset-flow) * 0.4);
    }

    &:where(li)::marker {
      color: var(--muted-foreground);
    }

    &:where(dt) {
      font-weight: 600;
    }

    &:where(dd) {
      padding-inline-start: 1.5em;
    }

    &:where(blockquote) {
      border-inline-start: 2px solid var(--border);
      color: var(--muted-foreground);
      padding-inline-start: 1em;
    }

    &:where(hr) {
      border: 0;
      border-block-start: 1px solid var(--border);
    }

    &:where(* + hr, hr + *) {
      margin-block-start: calc(var(--typeset-flow) * 2);
    }

    &:where(pre) {
      background-color: color-mix(in oklab, var(--muted) 50%, transparent);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      font-size: 0.875em;
      line-height: 1.7;
      overflow-x: auto;
      padding: 0.85em 1.15em;
    }

    &:where(pre code) {
      font-size: inherit;
    }

    &:where(img, video, svg, canvas, iframe) {
      max-width: 100%;
    }

    &:where(img, video) {
      border-radius: var(--radius);
      height: auto;
    }

    &:where(figcaption) {
      color: var(--muted-foreground);
      font-size: 0.875em;
    }

    &:where(* + figcaption) {
      margin-block-start: 0.75em;
    }

    &:where(details) {
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 0.5em 1em;
    }

    &:where(summary) {
      cursor: pointer;
      font-weight: 500;
    }

    &:where(table) {
      border-collapse: collapse;
      font-size: 0.875em;
      font-variant-numeric: tabular-nums;
      line-height: 1.6;
      width: 100%;
    }

    &:where(th) {
      font-weight: 600;
      text-align: start;
    }

    &:where(th, td) {
      border-block-end: 1px solid var(--border);
      padding: 0.6em 0.75em;
      vertical-align: top;
    }

    &:where(th[align="center"], td[align="center"]) {
      text-align: center;
    }

    &:where(th[align="right"], td[align="right"]) {
      text-align: end;
    }

    &:where(:is(th, td):first-child) {
      padding-inline-start: 0;
    }
  }

  .typeset-scroll {
    max-width: 100%;
    overflow-x: auto;
  }

  .typeset * + .typeset-scroll {
    margin-block-start: var(--typeset-flow);
  }
}

import { cn } from '@gentleduck/libs/cn'
import { Slot } from '@gentleduck/primitives/slot'
import type { Variants } from '@gentleduck/variants'
import * as React from 'react'
import { typesetVariants } from './typeset.constants'

interface ITypesetProps extends React.HTMLAttributes<HTMLDivElement>, Variants.VariantProps<typeof typesetVariants> {
  asChild?: boolean
}

const Typeset = React.forwardRef<HTMLDivElement, ITypesetProps>(
  ({ className, size = 'default', asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : 'div'
    return <Comp className={cn(typesetVariants({ size }), className)} data-slot="typeset" ref={ref} {...props} />
  },
)
Typeset.displayName = 'Typeset'

export { Typeset }
